import {REGIONS,TERRITORIES,createGame,ownedIds,enemiesOf,placeTroops,attackRound,blitz,fortify,setPhase,endTurn,aiTurn,validateState,canPlayerAttack,tradeCards} from './engine.mjs';

const $=s=>document.querySelector(s);
const els={map:$('#map'),players:$('#players'),regions:$('#regions'),round:$('#round'),phaseTitle:$('#phaseTitle'),turnLabel:$('#turnLabel'),reinforcements:$('#reinforcements'),reinforceBox:$('#reinforceBox'),orderTitle:$('#orderTitle'),orderText:$('#orderText'),turnStatus:$('#turnStatus'),cardsBox:$('#cardsBox'),selection:$('#selectionInfo'),battle:$('#battleResult'),controls:$('#actionControls'),phaseBtn:$('#phaseBtn'),log:$('#log'),startModal:$('#startModal'),helpModal:$('#helpModal'),diceModal:$('#diceModal'),mapGuide:$('#mapGuide'),toast:$('#toast')};
let state=null,difficulty='normal',selectedFrom=null,selectedTo=null,selectedDice=3,toastTimer=null,aiBusy=false,rolling=false;
const SAVE='fronteras-acero-save-v2';
const regionShapes={north:'M90 80 L610 55 L650 210 L500 260 L315 220 L115 245 Z',west:'M45 250 L320 225 L365 515 L175 615 L55 520 Z',crown:'M315 225 L650 210 L665 530 L360 515 Z',ember:'M70 525 L365 515 L520 720 L115 710 Z',sun:'M520 515 L820 500 L900 710 L520 720 Z',isles:'M665 105 L900 120 L965 555 L820 660 L665 530 Z'};
const regionLabelPos={north:[365,92],west:[140,390],crown:[500,365],ember:[270,665],sun:[670,650],isles:[840,330]};
const tById=id=>TERRITORIES.find(t=>t.id===id);

function save(){if(state)localStorage.setItem(SAVE,JSON.stringify({state,difficulty}));}
function load(){try{const d=JSON.parse(localStorage.getItem(SAVE));if(!d?.state||d.state.version!==2||validateState(d.state).length)return false;state=d.state;difficulty=d.difficulty||'normal';return true}catch{return false}}
function showToast(msg){els.toast.textContent=msg;els.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>els.toast.classList.remove('show'),2400)}
function regionShort(key){return {north:'NORTE',west:'OESTE',crown:'CORONA',ember:'BRASA',sun:'SOL',isles:'JADE'}[key]}

function initMap(){
  els.map.innerHTML=`<defs><filter id="glow"><feGaussianBlur stdDeviation="5" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><ellipse class="sea-ring" cx="500" cy="380" rx="470" ry="335"/><ellipse class="sea-ring" cx="500" cy="380" rx="410" ry="285"/>`;
  for(const [key,path] of Object.entries(regionShapes)){const [x,y]=regionLabelPos[key];els.map.insertAdjacentHTML('beforeend',`<path d="${path}" fill="${REGIONS[key].color}12" stroke="${REGIONS[key].color}45" stroke-width="3"/><text class="region-label" x="${x}" y="${y}">${REGIONS[key].name.toUpperCase()}</text>`)}
  const drawn=new Set();for(const t of TERRITORIES)for(const n of t.n){const k=[t.id,n].sort().join('-');if(drawn.has(k))continue;drawn.add(k);const b=tById(n),cross=t.region!==b.region?' cross':'';els.map.insertAdjacentHTML('beforeend',`<line class="connection${cross}" x1="${t.x*10}" y1="${t.y*8}" x2="${b.x*10}" y2="${b.y*8}"/>`)}
  for(const t of TERRITORIES){const x=t.x*10,y=t.y*8,r=49,points=Array.from({length:8},(_,i)=>{const a=Math.PI*2*i/8+.18,rr=r*(i%2?1:.88);return`${x+Math.cos(a)*rr},${y+Math.sin(a)*rr}`}).join(' ');els.map.insertAdjacentHTML('beforeend',`<g class="territory" id="terr-${t.id}" data-id="${t.id}" tabindex="0" role="button" aria-label="${t.name}"><polygon class="territory-shape" points="${points}" style="--region:${REGIONS[t.region].color}"/><text class="territory-region" x="${x}" y="${y-29}">${regionShort(t.region)}</text><text class="territory-label" x="${x}" y="${y-13}">${t.name}</text><circle class="army-disc" cx="${x}" cy="${y+17}" r="21"/><path class="army-icon" d="M${x-5} ${y+18}h10v10h-10zM${x-8} ${y+12}h16l-3-7h-10z"/><text class="army-count" x="${x+18}" y="${y+24}">1</text></g>`)}
  els.map.addEventListener('click',e=>{const g=e.target.closest('.territory');if(g)territoryClick(g.dataset.id,e.shiftKey)});
  els.map.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.closest('.territory')){e.preventDefault();territoryClick(e.target.closest('.territory').dataset.id)}});
}

function render(){if(!state)return;const p=state.players[state.current];els.round.textContent=state.turn;els.reinforcements.textContent=state.pendingReinforcements;els.reinforceBox.style.display=state.phase==='reinforce'?'block':'none';els.turnLabel.textContent=p.human?'TU TURNO':`TURNO DE ${p.name.toUpperCase()}`;renderFlow();renderPlayers();renderRegions();renderMap();renderGuide();renderPanel();renderLog();save()}
function renderFlow(){const order=['reinforce','attack','fortify','close'],idx=state.phase==='gameover'?4:Math.max(0,order.indexOf(state.phase));document.querySelectorAll('.flow-step').forEach((el,i)=>{el.classList.toggle('active',i===idx);el.classList.toggle('done',i<idx)})}
function renderPlayers(){els.players.innerHTML=state.players.map(p=>{const ids=ownedIds(state,p.id),troops=ids.reduce((s,id)=>s+state.territories[id].troops,0);return`<div class="player ${state.current===p.id?'active':''} ${!p.alive?'eliminated':''}" style="--pc:${p.color}"><div class="player-top"><i class="player-color"></i><span class="player-name">${p.name}</span>${state.current===p.id&&p.alive?'<span class="turn-badge">EN TURNO</span>':''}</div><div class="player-stats"><span><strong>${ids.length}</strong> territorios</span><span><strong>${troops}</strong> tropas</span><span><strong>${p.cards}</strong> cartas</span></div></div>`}).join('')}
function renderRegions(){els.regions.innerHTML=Object.entries(REGIONS).map(([k,r])=>{const owner=state.players.find(p=>TERRITORIES.filter(t=>t.region===k).every(t=>state.territories[t.id].owner===p.id));return`<div class="region-row" style="--rc:${r.color}"><i class="region-swatch"></i><span>${r.name}${owner?` · ${owner.name}`:''}</span><strong>+${r.bonus}</strong></div>`}).join('')}
function renderMap(){for(const t of TERRITORIES){const d=state.territories[t.id],p=state.players[d.owner],g=$(`#terr-${t.id}`);g.style.setProperty('--owner',p.color);g.classList.toggle('owned',d.owner===state.current);g.classList.toggle('selected',t.id===selectedFrom||t.id===selectedTo);g.classList.toggle('target',selectedFrom&&state.phase==='attack'&&enemiesOf(state,selectedFrom).includes(t.id));g.querySelector('.army-count').textContent=d.troops;g.setAttribute('aria-label',`${t.name}, región ${REGIONS[t.region].name}, ${d.troops} tropas, pertenece a ${p.name}`)}}
function renderLog(){els.log.innerHTML=state.log.slice(0,8).map(l=>`<div class="log-item" style="--lc:${l.p===null?'#788896':state.players[l.p]?.color||'#788896'}"><i class="log-dot"></i><span>${l.text}</span></div>`).join('')}
function setGuide(step,title,text){els.mapGuide.innerHTML=`<span>${step}</span><strong>${title}</strong><small>${text}</small>`}
function renderGuide(){if(!state.players[state.current].human){setGuide('…',`${state.players[state.current].name} está jugando`,'Espera a que el rival termine sus decisiones.');return}if(state.phase==='reinforce')setGuide('1','Pulsa tus territorios luminosos',`Coloca las ${state.pendingReinforcements} tropas restantes antes de combatir.`);else if(state.phase==='attack'&&!selectedFrom)setGuide('1','Elige el territorio atacante','Debe ser tuyo, tener 2+ tropas y limitar con un enemigo.');else if(state.phase==='attack'&&!selectedTo)setGuide('2','Elige un vecino enemigo','Los objetivos válidos parpadean con un borde rojo.');else if(state.phase==='attack')setGuide('3','Configura y lanza los dados','El resultado se mostrará antes de volver al mapa.');else if(state.phase==='fortify'&&!selectedFrom)setGuide('1','Elige el origen de la maniobra','Debe tener al menos 2 tropas. También puedes pasar.');else if(state.phase==='fortify'&&!selectedTo)setGuide('2','Elige el destino propio','Puede conectarse mediante una ruta continua de tus territorios.');else if(state.phase==='fortify')setGuide('3','Confirma cuántas tropas mover','Siempre quedará al menos una tropa en el origen.');else if(state.phase==='close')setGuide('4','Revisa el cierre del turno',state.conqueredThisTurn?'Recibirás una carta antes de pasar al siguiente jugador.':'No conquistaste, por lo que no recibes carta.')}

function renderCards(){const p=state.players[state.current];if(!p.human){els.cardsBox.innerHTML=`<span>Cartas de ${p.name}</span><strong>${p.cards}</strong>`;return}const can=state.phase==='reinforce'&&p.cards>=3,forced=p.cards>=5;els.cardsBox.innerHTML=`<span>🂠 <strong>${p.cards}</strong> cartas ${forced?'<em>· canje obligatorio</em>':''}</span><button id="tradeBtn" ${can?'':'disabled'}>${can?'Canjear 3':'Necesitas 3'}</button>`;const btn=$('#tradeBtn');if(btn)btn.onclick=()=>{const r=tradeCards(state);if(r.ok){showToast(`Canje completado: +${r.bonus} tropas`);render()}}}
function renderPanel(){const human=state.players[state.current].human;els.battle.innerHTML='';els.controls.innerHTML='';els.selection.innerHTML='';renderCards();
  if(state.phase==='gameover'){const won=state.winner===0;els.phaseTitle.textContent=won?'Victoria total':'Campaña terminada';els.orderTitle.textContent=won?'El continente es tuyo':'Has sido derrotado';els.orderText.textContent=won?'Todos los estandartes enemigos han caído.':'Tus últimos territorios fueron conquistados.';els.turnStatus.innerHTML=won?'<strong>Objetivo cumplido:</strong> controlas los 24 territorios.':'La campaña puede reiniciarse cuando quieras.';els.selection.innerHTML=`<div class="victory"><h3>${won?'¡Victoria!':'Fin de la partida'}</h3><p>${won?'La historia recordará tu campaña.':'Prueba una nueva distribución y dificultad.'}</p></div>`;els.phaseBtn.textContent='Nueva partida';els.phaseBtn.disabled=false;return}
  if(!human){els.phaseTitle.textContent='Turno enemigo';els.orderTitle.textContent=`${state.players[state.current].name} está actuando`;els.orderText.textContent='La inteligencia rival completa reclutamiento, combate y maniobra.';els.turnStatus.innerHTML='<strong>Espera:</strong> tu turno comenzará automáticamente.';els.phaseBtn.textContent='Procesando…';els.phaseBtn.disabled=true;return}
  els.phaseBtn.disabled=false;
  if(state.phase==='reinforce'){const forced=state.players[state.current].cards>=5;els.phaseTitle.textContent='Paso 1 · Reclutamiento';els.orderTitle.textContent=forced?'Canje obligatorio':`${state.pendingReinforcements} tropas por desplegar`;els.orderText.textContent=forced?'Tienes 5 o más cartas. Canjea un trío antes de colocar tropas.':'Pulsa cualquier territorio propio para añadir 1 tropa. Con Shift + clic puedes añadir hasta 5.';els.turnStatus.innerHTML=`<strong>Objetivo:</strong> coloca todas tus tropas. Al terminar, el juego abrirá automáticamente el combate.`;els.phaseBtn.textContent=forced?'Canjea cartas para continuar':'Coloca todos los refuerzos';els.phaseBtn.disabled=true}
  else if(state.phase==='attack'){const possible=canPlayerAttack(state);els.phaseTitle.textContent='Paso 2 · Combate';els.orderTitle.textContent=selectedTo?'Ataque preparado':selectedFrom?'Ahora elige el objetivo':'Declara un ataque';els.orderText.textContent='Origen propio → vecino enemigo → dados → resultado. Los empates siempre favorecen al defensor.';els.turnStatus.innerHTML=state.attackMadeThisTurn?'<strong>Tirada obligatoria cumplida.</strong> Puedes seguir atacando o pasar a maniobra.':possible?'<strong>Ataque obligatorio pendiente.</strong> Debes resolver al menos una tirada.':'<strong>Excepción aplicada:</strong> no tienes ningún ataque legal y puedes continuar.';els.phaseBtn.textContent=state.attackMadeThisTurn||!possible?'Finalizar combate →':'Debes atacar antes de continuar';els.phaseBtn.disabled=possible&&!state.attackMadeThisTurn;if(selectedFrom){const a=state.territories[selectedFrom];els.selection.innerHTML=`<div class="selection-item"><span>Origen · ${tById(selectedFrom).name}</span><strong>${a.troops} tropas</strong></div>`}if(selectedTo)renderAttackControls()}
  else if(state.phase==='fortify'){els.phaseTitle.textContent='Paso 3 · Maniobra';els.orderTitle.textContent=selectedTo?'Movimiento preparado':selectedFrom?'Elige el destino':'Fortifica o pasa';els.orderText.textContent='Puedes hacer un solo movimiento por una ruta continua de territorios propios. Deja siempre 1 tropa en el origen.';els.turnStatus.innerHTML=`<strong>Opcional:</strong> mueve tropas una vez o pulsa “Pasar maniobra”. Después se robará carta si conquistaste.`;els.phaseBtn.textContent='Pasar maniobra y cerrar turno';if(selectedFrom){const a=state.territories[selectedFrom];els.selection.innerHTML=`<div class="selection-item"><span>Origen · ${tById(selectedFrom).name}</span><strong>${a.troops} tropas</strong></div>`}if(selectedTo)renderFortifyControls()}
  else if(state.phase==='close'){els.phaseTitle.textContent='Paso 4 · Cierre';els.orderTitle.textContent=state.conqueredThisTurn?'Has ganado una carta':'Cierre sin carta';els.orderText.textContent=state.conqueredThisTurn?'Conquistaste al menos un territorio. Al cerrar, robarás 1 carta del mazo.':'No conquistaste ningún territorio durante este turno.';els.turnStatus.innerHTML=`<strong>Resumen:</strong> combate ${state.attackMadeThisTurn?'realizado':'sin ataques legales'} · maniobra resuelta · ${state.conqueredThisTurn?'1 carta pendiente':'0 cartas'}.`;els.phaseBtn.textContent=state.conqueredThisTurn?'Robar carta y pasar turno →':'Pasar al siguiente jugador →'}
}
function renderAttackControls(){const a=state.territories[selectedFrom],d=state.territories[selectedTo],max=Math.min(3,a.troops-1);selectedDice=Math.min(selectedDice,max);els.selection.innerHTML=`<div class="selection-item"><span>Atacante · ${tById(selectedFrom).name}</span><strong>${a.troops} tropas</strong></div><div class="selection-item"><span>Defensor · ${tById(selectedTo).name}</span><strong>${d.troops} tropas</strong></div>`;els.controls.innerHTML=`<label>Dados del atacante (máximo ${max})</label><div class="dice-choice">${[1,2,3].filter(n=>n<=max).map(n=>`<button data-dice="${n}" class="${n===selectedDice?'active':''}">${n} dado${n>1?'s':''}</button>`).join('')}</div><button class="primary-btn" id="rollBtn">🎲 Lanzar una ronda</button><button class="secondary-btn" id="blitzBtn">Ataque rápido hasta conquistar o retirarse</button>`;document.querySelectorAll('[data-dice]').forEach(b=>b.onclick=()=>{selectedDice=+b.dataset.dice;renderPanel()});$('#rollBtn').onclick=()=>doAttack(false);$('#blitzBtn').onclick=()=>doAttack(true)}
function renderFortifyControls(){const max=state.territories[selectedFrom].troops-1;if(max<1)return;els.selection.innerHTML+=`<div class="selection-item"><span>Destino · ${tById(selectedTo).name}</span><strong>${state.territories[selectedTo].troops} tropas</strong></div>`;els.controls.innerHTML=`<label>Tropas a mover: <strong id="moveVal">1</strong><input id="moveRange" type="range" min="1" max="${max}" value="1"></label><button class="primary-btn" id="moveBtn">Confirmar movimiento → cierre</button>`;$('#moveRange').oninput=e=>$('#moveVal').textContent=e.target.value;$('#moveBtn').onclick=()=>{if(fortify(state,selectedFrom,selectedTo,+$('#moveRange').value)){selectedFrom=selectedTo=null;render()}else showToast('No existe una ruta continua entre esos territorios')}}

function territoryClick(id,shift=false){if(!state||aiBusy||rolling||state.winner!==null||!state.players[state.current].human)return;const d=state.territories[id];if(state.phase==='reinforce'){if(state.players[state.current].cards>=5)return showToast('Debes canjear cartas antes de desplegar');if(d.owner!==state.current)return showToast('Elige uno de tus territorios luminosos');const amount=Math.min(shift?5:1,state.pendingReinforcements);placeTroops(state,id,amount);render();return}if(state.phase==='attack'){if(d.owner===state.current){if(d.troops<2)return showToast('Ese territorio necesita al menos 2 tropas');if(!enemiesOf(state,id).length)return showToast('Ese territorio no limita con ningún enemigo');selectedFrom=id;selectedTo=null;selectedDice=Math.min(3,d.troops-1);render();return}if(selectedFrom&&enemiesOf(state,selectedFrom).includes(id)){selectedTo=id;render();return}showToast(selectedFrom?'El objetivo debe estar conectado por una línea':'Primero elige el territorio atacante')}else if(state.phase==='fortify'){if(d.owner!==state.current)return showToast('La maniobra solo conecta territorios propios');if(!selectedFrom){if(d.troops<2)return showToast('El origen necesita al menos 2 tropas');selectedFrom=id}else if(id===selectedFrom){selectedFrom=null;selectedTo=null}else selectedTo=id;render()}}

function diceMarkup(values,rollingClass=''){return values.map(v=>`<i class="big-die ${rollingClass}">${v}</i>`).join('')}
function comparisonMarkup(r){const rows=[];for(let i=0;i<Math.min(r.attackerDice.length,r.defenderDice.length);i++){const a=r.attackerDice[i],d=r.defenderDice[i],attackerWins=a>d;rows.push(`<div class="compare-row"><span>🎲 ${a}</span><b>${attackerWins?'vence a':'pierde ante'} </b><span>${d} 🎲</span><em>−1 ${attackerWins?'defensor':'atacante'}${a===d?' (empate)':''}</em></div>`)}return rows.join('')}
async function doAttack(fast){if(rolling)return;rolling=true;const from=selectedFrom,to=selectedTo,maxDice=fast?Math.min(3,state.territories[from].troops-1):selectedDice,defDice=Math.min(2,state.territories[to].troops);els.diceModal.classList.remove('hidden');$('#diceTitle').textContent='Los dados están rodando…';$('#battleRoute').textContent=`${tById(from).name} ataca ${tById(to).name}`;$('#comparison').innerHTML='';$('#closeDice').classList.remove('visible');let fakeA=Array(maxDice).fill(1),fakeD=Array(defDice).fill(1);$('#attackerDice').innerHTML=diceMarkup(fakeA,'rolling');$('#defenderDice').innerHTML=diceMarkup(fakeD,'rolling');const ticker=setInterval(()=>{fakeA=fakeA.map(()=>1+Math.floor(Math.random()*6));fakeD=fakeD.map(()=>1+Math.floor(Math.random()*6));$('#attackerDice').innerHTML=diceMarkup(fakeA,'rolling');$('#defenderDice').innerHTML=diceMarkup(fakeD,'rolling')},110);await new Promise(r=>setTimeout(r,950));clearInterval(ticker);const result=fast?blitz(state,from,to):attackRound(state,from,to,selectedDice);const r=fast?result.rounds.at(-1):result;if(!result.ok||!r){els.diceModal.classList.add('hidden');rolling=false;return}$('#attackerDice').innerHTML=diceMarkup(r.attackerDice);$('#defenderDice').innerHTML=diceMarkup(r.defenderDice);const aLoss=fast?result.rounds.reduce((s,x)=>s+x.attackerLosses,0):r.attackerLosses,dLoss=fast?result.rounds.reduce((s,x)=>s+x.defenderLosses,0):r.defenderLosses;$('#diceTitle').textContent=r.conquered?'¡Territorio conquistado!':'Resultado de la tirada';$('#comparison').innerHTML=`${comparisonMarkup(r)}<div class="battle-summary"><strong>${fast?`${result.rounds.length} rondas resueltas. `:''}Pérdidas:</strong> ${aLoss} atacante${aLoss===1?'':'s'} · ${dLoss} defensor${dLoss===1?'':'es'}.${r.conquered?' El territorio cambia de dueño.':' Puedes atacar otra vez o retirarte.'}</div>`;$('#closeDice').classList.add('visible');if(r.conquered){selectedFrom=to;selectedTo=null}else if(state.territories[from].troops<2){selectedFrom=selectedTo=null}render();rolling=false}
$('#closeDice').onclick=()=>{els.diceModal.classList.add('hidden');render()};
els.phaseBtn.onclick=()=>{if(!state||rolling)return;if(state.phase==='gameover'){openStart();return}if(state.phase==='attack'){if(!setPhase(state,'fortify'))return showToast('Debes lanzar los dados al menos una vez');selectedFrom=selectedTo=null;render()}else if(state.phase==='fortify'){setPhase(state,'close');selectedFrom=selectedTo=null;render()}else if(state.phase==='close'){const earned=state.conqueredThisTurn;endTurn(state);selectedFrom=selectedTo=null;render();if(earned)showToast('Carta robada. Comienza el siguiente turno.');runAiTurns()}};
async function runAiTurns(){if(!state||state.winner!==null||state.players[state.current].human)return;aiBusy=true;while(state.winner===null&&!state.players[state.current].human){render();await new Promise(r=>setTimeout(r,700));aiTurn(state,state.current,difficulty);render();await new Promise(r=>setTimeout(r,520))}aiBusy=false;render()}
function startNew(){state=createGame({players:+$('#playerCount').value,seed:Date.now(),human:true});difficulty=$('#difficulty').value;selectedFrom=selectedTo=null;els.startModal.classList.add('hidden');render();showToast('Paso 1: coloca todos tus refuerzos')}
function openStart(){els.startModal.classList.remove('hidden');$('#continueBtn').hidden=!localStorage.getItem(SAVE)}
$('#startBtn').onclick=startNew;$('#continueBtn').onclick=()=>{if(load()){els.startModal.classList.add('hidden');render();runAiTurns()}};$('#newBtn').onclick=openStart;$('#helpBtn').onclick=()=>els.helpModal.classList.remove('hidden');$('#closeHelp').onclick=$('#gotItBtn').onclick=()=>els.helpModal.classList.add('hidden');window.addEventListener('beforeunload',save);

function registerWebMCP(){const c=document.modelContext;if(!c?.registerTool)return;try{c.registerTool({name:'get_campaign_state',title:'Consultar campaña',description:'Devuelve turno, fase, cartas, jugadores y territorios.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>state?{turn:state.turn,phase:state.phase,currentPlayer:state.players[state.current].name,attackRequired:state.phase==='attack'&&!state.attackMadeThisTurn&&canPlayerAttack(state),cards:state.players[state.current].cards,winner:state.winner===null?null:state.players[state.winner].name}:{status:'no_game'}});c.registerTool({name:'start_new_campaign',title:'Iniciar campaña',description:'Inicia una campaña con entre 2 y 4 ejércitos.',inputSchema:{type:'object',properties:{players:{type:'integer',minimum:2,maximum:4},difficulty:{type:'string',enum:['fácil','normal','difícil']}},required:['players','difficulty'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({players,difficulty:d})=>{state=createGame({players,human:true});difficulty=d;els.startModal.classList.add('hidden');render();return{status:'started',players,difficulty:d}}})}catch(e){console.warn('WebMCP no disponible',e)}}

initMap();if(localStorage.getItem(SAVE))$('#continueBtn').hidden=false;registerWebMCP();
